private static void validatePort(String uriStr) throws RuntimeException {
    Pattern p = Pattern.compile("^[a-zA-Z][a-zA-Z0-9+\\-.]*://[^/]*:(-?\\d+)(?:/.*)?$");
    Matcher m = p.matcher(uriStr);
    if (m.find()) {
        try {
            int port = Integer.parseInt(m.group(1));
            if (port < 0 || port > 65535) {
                throw createJsonSchemaException("Wrong MetaSchema URI: " + uriStr, null);
            }
        } catch (NumberFormatException ignored) {}
    }
}

